namespace sv_192e6d0e079d4b3da8db7b13fc61dc95.Services;

public record TaskItem(int Id, string Title, string Assignee, string Priority, DateTime DueDate, string Status);

public interface ITaskService
{
    Task<List<TaskItem>> GetAllTasksAsync();
    Task<TaskItem> CreateTaskAsync(string title, string assignee, string priority, DateTime dueDate);
    Task UpdateTaskStatusAsync(int taskId, string newStatus);
}

@page "/board"
@using sv_192e6d0e079d4b3da8db7b13fc61dc95.Services
@inject ITaskService TaskService
@rendermode InteractiveServer

<PageTitle>Kanban Board</PageTitle>

<h1 class="mb-4">Kanban Board</h1>

@if (_loading)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (_error is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error loading tasks:</strong> @_error
        <button class="btn btn-outline-danger btn-sm ms-3" @onclick="LoadTasksAsync">Retry</button>
    </div>
}
else
{
    <!-- Stats Bar -->
    <div class="row g-2 mb-3">
        <div class="col">
            <div class="card text-center">
                <div class="card-body py-2">
                    <div class="fw-bold">@FilteredTasks.Count</div>
                    <small class="text-muted">Total</small>
                </div>
            </div>
        </div>
        @foreach (var col in Columns)
        {
            <div class="col">
                <div class="card text-center">
                    <div class="card-body py-2">
                        <div class="fw-bold">@GetColumnTasks(col).Count</div>
                        <small class="text-muted">@col</small>
                    </div>
                </div>
            </div>
        }
        <div class="col">
            <div class="card text-center border-danger">
                <div class="card-body py-2">
                    <div class="fw-bold text-danger">@OverdueCount</div>
                    <small class="text-muted">Overdue</small>
                </div>
            </div>
        </div>
    </div>

    <!-- Search Bar -->
    <div class="mb-3">
        <input type="text"
               class="form-control"
               placeholder="Search tasks by title..."
               @bind="_searchText"
               @bind:event="oninput" />
    </div>

    <!-- Kanban Columns -->
    <div class="row">
        @for (var i = 0; i < Columns.Length; i++)
        {
            var colIndex = i;
            var colName = Columns[colIndex];
            var tasks = GetColumnTasks(colName);

            <div class="col-md-4">
                <div class="card">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>@colName</strong>
                        <span class="badge bg-secondary">@tasks.Count</span>
                    </div>
                    <div class="card-body" style="min-height: 200px;">
                        @foreach (var task in tasks)
                        {
                            <div class="card mb-2">
                                <div class="card-body p-2">
                                    <h6 class="card-title mb-1">@task.Title</h6>
                                    <p class="card-text mb-1">
                                        <small class="text-muted">@task.Assignee</small>
                                    </p>
                                    <div class="d-flex justify-content-between align-items-center mb-1">
                                        <span class="badge @GetPriorityClass(task.Priority)">@task.Priority</span>
                                        <small class="text-muted">@task.DueDate.ToString("MMM dd")</small>
                                    </div>
                                    <div class="d-flex gap-1">
                                        @if (colIndex > 0)
                                        {
                                            <button class="btn btn-outline-secondary btn-sm"
                                                    disabled="@_moving"
                                                    @onclick="() => MoveTaskAsync(task.Id, Columns[colIndex - 1])">
                                                &larr; Move Left
                                            </button>
                                        }
                                        @if (colIndex < Columns.Length - 1)
                                        {
                                            <button class="btn btn-outline-secondary btn-sm"
                                                    disabled="@_moving"
                                                    @onclick="() => MoveTaskAsync(task.Id, Columns[colIndex + 1])">
                                                Move Right &rarr;
                                            </button>
                                        }
                                    </div>
                                </div>
                            </div>
                        }

                        <!-- Inline Add Task Form -->
                        @if (_addingToColumn == colName)
                        {
                            <div class="card border-primary mt-2">
                                <div class="card-body p-2">
                                    <div class="mb-2">
                                        <input type="text" class="form-control form-control-sm"
                                               placeholder="Title"
                                               @bind="_newTitle" />
                                    </div>
                                    <div class="mb-2">
                                        <input type="text" class="form-control form-control-sm"
                                               placeholder="Assignee"
                                               @bind="_newAssignee" />
                                    </div>
                                    <div class="mb-2">
                                        <select class="form-select form-select-sm" @bind="_newPriority">
                                            <option value="High">High</option>
                                            <option value="Medium">Medium</option>
                                            <option value="Low">Low</option>
                                        </select>
                                    </div>
                                    <div class="mb-2">
                                        <input type="date" class="form-control form-control-sm"
                                               @bind="_newDueDate" />
                                    </div>
                                    <div class="d-flex gap-1">
                                        <button class="btn btn-primary btn-sm"
                                                disabled="@_saving"
                                                @onclick="() => SaveTaskAsync(colName)">
                                            @(_saving ? "Saving..." : "Save")
                                        </button>
                                        <button class="btn btn-outline-secondary btn-sm"
                                                disabled="@_saving"
                                                @onclick="CancelAdd">
                                            Cancel
                                        </button>
                                    </div>
                                    @if (_formError is not null)
                                    {
                                        <div class="text-danger mt-1"><small>@_formError</small></div>
                                    }
                                </div>
                            </div>
                        }
                    </div>
                    @if (_addingToColumn != colName)
                    {
                        <div class="card-footer">
                            <button class="btn btn-outline-primary btn-sm w-100"
                                    @onclick="() => StartAdd(colName)">
                                + Add Task
                            </button>
                        </div>
                    }
                </div>
            </div>
        }
    </div>
}

@code {
    private static readonly string[] Columns = ["To Do", "In Progress", "Done"];

    private List<TaskItem> _tasks = [];
    private bool _loading = true;
    private string? _error;
    private string _searchText = string.Empty;

    // Move state
    private bool _moving;

    // Add-task form state
    private string? _addingToColumn;
    private string _newTitle = string.Empty;
    private string _newAssignee = string.Empty;
    private string _newPriority = "Medium";
    private DateTime _newDueDate = DateTime.Today.AddDays(7);
    private bool _saving;
    private string? _formError;

    private List<TaskItem> FilteredTasks =>
        string.IsNullOrWhiteSpace(_searchText)
            ? _tasks
            : _tasks.Where(t => t.Title.Contains(_searchText, StringComparison.OrdinalIgnoreCase)).ToList();

    private int OverdueCount =>
        FilteredTasks.Count(t => t.DueDate.Date < DateTime.Today && t.Status != "Done");

    private List<TaskItem> GetColumnTasks(string status) =>
        FilteredTasks.Where(t => t.Status == status).ToList();

    private static string GetPriorityClass(string priority) => priority switch
    {
        "High" => "bg-danger",
        "Medium" => "bg-warning text-dark",
        "Low" => "bg-success",
        _ => "bg-secondary"
    };

    protected override async Task OnInitializedAsync()
    {
        await LoadTasksAsync();
    }

    private async Task LoadTasksAsync()
    {
        _loading = true;
        _error = null;

        try
        {
            _tasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task MoveTaskAsync(int taskId, string newStatus)
    {
        _moving = true;

        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var index = _tasks.FindIndex(t => t.Id == taskId);
            if (index >= 0)
            {
                _tasks[index] = _tasks[index] with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _moving = false;
        }
    }

    private void StartAdd(string column)
    {
        _addingToColumn = column;
        _newTitle = string.Empty;
        _newAssignee = string.Empty;
        _newPriority = "Medium";
        _newDueDate = DateTime.Today.AddDays(7);
        _formError = null;
    }

    private void CancelAdd()
    {
        _addingToColumn = null;
        _formError = null;
    }

    private async Task SaveTaskAsync(string column)
    {
        if (string.IsNullOrWhiteSpace(_newTitle) || string.IsNullOrWhiteSpace(_newAssignee))
        {
            _formError = "Title and Assignee are required.";
            return;
        }

        _saving = true;
        _formError = null;

        try
        {
            var created = await TaskService.CreateTaskAsync(_newTitle.Trim(), _newAssignee.Trim(), _newPriority, _newDueDate);
            // The service creates tasks; if the column isn't the default status, move it.
            if (created.Status != column)
            {
                await TaskService.UpdateTaskStatusAsync(created.Id, column);
                created = created with { Status = column };
            }
            _tasks.Add(created);
            _addingToColumn = null;
        }
        catch (Exception ex)
        {
            _formError = ex.Message;
        }
        finally
        {
            _saving = false;
        }
    }
}

namespace sv_192e6d0e079d4b3da8db7b13fc61dc95.Services;

